class MagixCore{constructor(){this.header=document.getElementById("header"),this.footbar=document.getElementById("footbar"),this.init()}init(){this.initScrollEvents(),this.initGlobalClicks()}initScrollEvents(){(this.header||this.footbar)&&window.addEventListener("scroll",(()=>{const e=window.scrollY>100;this.header&&(e?this.header.classList.remove("at-top"):this.header.classList.add("at-top")),this.footbar&&(e?this.footbar.classList.remove("at-top"):this.footbar.classList.add("at-top"))}),{passive:!0})}initGlobalClicks(){document.addEventListener("click",(e=>{this.handleMobileDropdown(e),this.handleTargetBlank(e),this.handleYouTubeFacade(e)}))}handleMobileDropdown(e){const t=e.target.closest(".js-mobile-toggle");if(t&&"undefined"!=typeof bootstrap){e.preventDefault(),e.stopPropagation();const o=t.closest("a");bootstrap.Dropdown.getOrCreateInstance(o).toggle()}}handleTargetBlank(e){const t=e.target.closest("a.targetblank");t&&(e.preventDefault(),window.open(t.href,"_blank","noopener,noreferrer"))}handleYouTubeFacade(e){const t=e.target.closest(".magix-ytb-container");if(!t)return;e.preventDefault();const o=t.querySelector(".ytb-video-preview");if(o)try{const e=JSON.parse(o.getAttribute("data-ytb")),a=document.createElement("iframe"),r=`https://www.youtube.com/embed/${e.videoId}?autoplay=1&rel=${e.playerVars.rel}&fs=${e.playerVars.fs}&hd=${e.playerVars.hd}`;a.setAttribute("src",r),a.setAttribute("frameborder","0"),a.setAttribute("allow","accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"),a.setAttribute("allowfullscreen","true"),a.style.width="100%",a.style.height="100%",a.style.display="block",t.classList.add("is-playing"),t.replaceChild(a,o)}catch(e){console.error("Magix YouTube: Impossible de charger la vidéo.",e)}}}document.addEventListener("DOMContentLoaded",(()=>{new MagixCore}));